import React from "react";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ChatMorphProps = Record<string, any>;

const PhoneIcon: React.FC<{ color: string }> = ({ color }) => (
  <svg viewBox="0 0 24 24" fill={color} width="105" height="105" style={{ transform: 'rotate(-10deg)', transition: 'none' }}>
    <path d="M20.01 15.38c-1.23 0-2.42-.2-3.53-.56a.977.977 0 00-1.01.24l-1.57 1.97c-2.83-1.35-5.48-3.9-6.89-6.83l1.95-1.66c.27-.28.35-.67.24-1.02-.37-1.11-.56-2.3-.56-3.53 0-.54-.45-.99-.99-.99H4.19C3.65 3 3 3.24 3 3.99 3 13.28 10.73 21 20.01 21c.71 0 .99-.63.99-1.18v-3.45c0-.54-.45-.99-.99-.99z" />
  </svg>
);

const Waveforms: React.FC<{ progress: number; color: string }> = ({ progress, color }) => {
  const frame = useCurrentFrame();
  const opacity = interpolate(progress, [0, 0.2], [1, 0], { extrapolateRight: "clamp" });
  const scale = interpolate(progress, [0, 0.2], [1.25, 0.8], { extrapolateRight: "clamp" });

  const baseHeightsLeft = [16, 36, 52, 28];
  const baseHeightsRight = [28, 52, 36, 16];

  const leftX = interpolate(progress, [0, 1], [-225, -260]);
  const rightX = interpolate(progress, [0, 1], [225, 260]);

  return (
    <div style={{ position: 'absolute', left: '50%', top: '50%', width: 0, height: 0, transition: 'none' }}>
      {/* Left Waveform Group */}
      <div style={{
        position: 'absolute',
        left: leftX,
        top: 0,
        transform: `translate(-100%, -50%) scale(${scale})`,
        display: 'flex',
        gap: 12,
        opacity,
        alignItems: 'center',
        justifyContent: 'center',
        transition: 'none'
      }}>
        {baseHeightsLeft.map((base, i) => {
          const height = base + Math.sin(frame * 0.2 + i) * 14;
          return (
            <div
              key={`l-${i}`}
              style={{
                width: 8,
                height: Math.max(8, height),
                backgroundColor: color,
                borderRadius: 4,
                transition: 'none'
              }}
            />
          );
        })}
      </div>

      {/* Right Waveform Group */}
      <div style={{
        position: 'absolute',
        left: rightX,
        top: 0,
        transform: `translate(0, -50%) scale(${scale})`,
        display: 'flex',
        gap: 12,
        opacity,
        alignItems: 'center',
        justifyContent: 'center',
        transition: 'none'
      }}>
        {baseHeightsRight.map((base, i) => {
          const height = base + Math.sin(frame * 0.2 + i + 2) * 14;
          return (
            <div
              key={`r-${i}`}
              style={{
                width: 8,
                height: Math.max(8, height),
                backgroundColor: color,
                borderRadius: 4,
                transition: 'none'
              }}
            />
          );
        })}
      </div>
    </div>
  );
};

const ChatBody: React.FC<{ segments: { text: string, color: string }[]; typedChars: number }> = ({ segments, typedChars }) => {
  let remaining = typedChars;

  return (
    <div style={{
      marginTop: 48,
      fontSize: 41.8, // Increased by 10%
      lineHeight: 1.5,
      fontWeight: 400,
      fontFamily: 'Inter',
      whiteSpace: 'pre-wrap',
      transition: 'none'
    }}>
      {segments.map((seg, i) => {
        if (remaining <= 0) return null;
        const toTake = Math.min(seg.text.length, remaining);
        remaining -= toTake;
        const visibleText = seg.text.substring(0, toTake);

        return (
          <span key={i} style={{ color: seg.color, transition: 'none' }}>
            {visibleText}
          </span>
        );
      })}
    </div>
  );
};

const ChatMorph: React.FC<ChatMorphProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  accentColor = "#2ed5dd",
  phoneIconColor = "#2ef39d",
  cardBackgroundColor = "#0a0d14",
  agentText = "AGENT LIVE",
  pillText = "EN 🇺🇸",
  textSegments = [
    { text: "Hi, I can help you track your order.\n", color: "#ffffff", lang: "EN 🇺🇸" },
    { text: "Veo que fue enviado hoy. ", color: "#80c6ff", lang: "SP 🇪🇸" },
    { text: "Llegará demain avant midi.\n", color: "#7ee0a4", lang: "FR 🇫🇷" },
    { text: "遅延はありません。 ", color: "#cda4ed", lang: "JP 🇯🇵" },
    { text: "Everything is on schedule.", color: "#ffffff", lang: "EN 🇺🇸" },
  ],
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings mapped to FPS
  const morphStartFrame = Math.floor(fps * 2);
  const textStartFrame = morphStartFrame + 6;

  // Typewriter effect timings
  const totalChars = React.useMemo(() => textSegments.reduce((sum, seg) => sum + seg.text.length, 0), [textSegments]);
  const typingDurationFrames = 6 * fps; // Reduced to exactly 6 seconds

  const typedChars = Math.floor(
    interpolate(frame - textStartFrame, [0, typingDurationFrames], [0, totalChars], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  // Determine current language pill based on currently typed character
  let currentSegIndex = 0;
  let accumulatedChars = 0;
  for (let i = 0; i < textSegments.length; i++) {
    accumulatedChars += textSegments[i].text.length;
    if (typedChars === 0) {
      currentSegIndex = 0;
      break;
    }
    if (typedChars <= accumulatedChars) {
      currentSegIndex = i;
      break;
    }
    if (i === textSegments.length - 1) {
      currentSegIndex = i;
    }
  }

  const currentLang = textSegments[currentSegIndex]?.lang || pillText;

  // Introductory scale-in spring
  const introProgress = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 120 }
  });

  // Main morphing snap spring
  const morphProgress = spring({
    frame: frame - morphStartFrame,
    fps,
    config: { damping: 15, stiffness: 140 }
  });

  // Container dimensions interpolations
  const containerWidth = interpolate(morphProgress, [0, 1], [300, 1200]);
  const containerHeight = interpolate(morphProgress, [0, 1], [300, 460]);
  const containerRadius = interpolate(morphProgress, [0, 1], [150, 24]);

  // Internal glowing gradient interpolations
  const glowY = interpolate(morphProgress, [0, 1], [50, 0]);
  const glowOpacity = interpolate(morphProgress, [0, 1], [0.6, 0.4]);
  const glowRadiusX = interpolate(morphProgress, [0, 1], [70, 80]);
  const glowRadiusY = interpolate(morphProgress, [0, 1], [70, 50]);

  // Phone Icon transformations
  const pulse = Math.sin(frame * 0.1) * 0.05;
  const phoneOpacity = interpolate(morphProgress, [0, 0.2], [1, 0], { extrapolateRight: 'clamp' });
  const phoneScale = interpolate(morphProgress, [0, 0.2], [1 + pulse, 0.5], { extrapolateRight: 'clamp' });

  // Chat interface opacity
  const chatContentOpacity = interpolate(morphProgress, [0.4, 1], [0, 1], { extrapolateLeft: 'clamp' });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>

      {/* Stylized Reference Image Background Elements */}
      {!transparentBackground && (
        <div style={{
          position: 'absolute',
          width: '100%',
          height: '100%',
          pointerEvents: 'none',
          transition: "none",
        }}>
          {/* Top Teal Radial Glow */}
          <div style={{
            position: 'absolute',
            width: '100%',
            height: '100%',
            background: 'radial-gradient(ellipse at 50% 0%, rgba(14, 56, 56, 0.85) 0%, transparent 75%)',
            transition: "none",
          }} />
          {/* Dark Halftone/Dot Mesh Pattern */}
          <div style={{
            position: 'absolute',
            width: '100%',
            height: '100%',
            backgroundImage: 'radial-gradient(circle at center, rgba(0, 0, 0, 0.7) 2.5px, transparent 2.5px)',
            backgroundSize: '24px 24px',
            backgroundPosition: 'center',
            transition: "none",
          }} />
        </div>
      )}

      {/* Main Centered Composition Wrapper */}
      <div style={{
        position: 'absolute',
        width: '100%',
        height: '100%',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        transform: `scale(${introProgress})`,
        transition: "none"
      }}>

        <Waveforms progress={morphProgress} color={phoneIconColor} />

        {/* Dynamic Morphing Card */}
        <div style={{
          width: containerWidth,
          height: containerHeight,
          borderRadius: containerRadius,
          backgroundColor: cardBackgroundColor,
          border: '1px solid rgba(255, 255, 255, 0.08)',
          boxShadow: '0 24px 64px rgba(0,0,0,0.8)',
          position: 'relative',
          overflow: 'hidden',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          flexShrink: 0,
          transition: "none",
        }}>

          {/* Soft Top Glow Overlay */}
          <div style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            background: `radial-gradient(ellipse ${glowRadiusX}% ${glowRadiusY}% at 50% ${glowY}%, ${accentColor} 0%, transparent 80%)`,
            opacity: glowOpacity,
            mixBlendMode: 'screen',
            pointerEvents: 'none',
            transition: "none",
          }} />

          {/* Initial Phone State */}
          <div style={{
            position: 'absolute',
            opacity: phoneOpacity,
            transform: `scale(${phoneScale})`,
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            transition: "none",
          }}>
            <PhoneIcon color={phoneIconColor} />
          </div>

          {/* Target Chat Box State */}
          <div style={{
            position: 'absolute',
            width: '100%',
            height: '100%',
            padding: '48px 60px',
            boxSizing: 'border-box',
            opacity: chatContentOpacity,
            display: 'flex',
            flexDirection: 'column',
            transition: "none",
          }}>

            {/* Chat Header */}
            <div style={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              width: '100%',
              transition: "none"
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 14, transition: "none" }}>
                <div style={{ width: 12, height: 12, borderRadius: 6, backgroundColor: phoneIconColor, transition: "none" }} />
                <span style={{ color: '#ffffff', fontSize: 25, letterSpacing: 1.5, fontWeight: 600, transition: "none" }}>
                  {agentText}
                </span>
              </div>
              <div style={{
                backgroundColor: 'rgba(255,255,255,0.08)',
                padding: '11px 22px',
                borderRadius: 34,
                color: '#ffffff',
                fontSize: 31.5,
                fontWeight: 600,
                transition: "none"
              }}>
                {currentLang}
              </div>
            </div>

            {/* Multilingual Typing Body */}
            <ChatBody segments={textSegments} typedChars={typedChars} />

          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChatMorph;